head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getMaxMinYear]<br/>config.xml 에 설정된 maxYear 와 minYear 값을 포함한 객체를 반환합니다.",
    "validation" : [
        "maxYear 와 minYear 속성을 포함한 객체를 반환해야 합니다.",
        "result.maxYear 는 config.xml 의 /WebSquare/date/maxYear/@value 에서 가져와야 합니다. 기본값은 2099 입니다.",
        "result.minYear 는 config.xml 의 /WebSquare/date/minYear/@value 에서 가져와야 합니다. 기본값은 1901 입니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getMaxMinYear_onclick = function () {
    var ret = $p.getMaxMinYear();
    wf_body_bottom.getObj("scwin").setReturnValue("getMaxMinYear() : {maxYear: " + ret.maxYear + ", minYear: " + ret.minYear + "}");
}
